    # ------------------------------------------------------------------
    # Screen navigation history (back/forward)
    # ------------------------------------------------------------------
    def _push_screen_history(self, screen_id):
        """Record a screen visit for back/forward navigation."""
        hist = getattr(self, '_screen_history', None)
        if hist is None:
            self._screen_history = hist = []
            self._history_index = -1
        # Truncate forward history on a new navigation
        if self._history_index < len(hist) - 1:
            del hist[self._history_index + 1:]
        # Avoid duplicate consecutive entries
        if not hist or hist[-1] != screen_id:
            hist.append(screen_id)
            # Cap history length
            if len(hist) > 50:
                del hist[0]
        self._history_index = len(hist) - 1
        self._update_nav_history_buttons()

    def _update_nav_history_buttons(self):
        """Enable/disable back/forward buttons based on history position."""
        try:
            hist = getattr(self, '_screen_history', []) or []
            idx = getattr(self, '_history_index', -1)
            if hasattr(self, '_back_btn'):
                self._back_btn.configure(state='normal' if idx > 0 else 'disabled')
            if hasattr(self, '_fwd_btn'):
                self._fwd_btn.configure(
                    state='normal' if 0 <= idx < len(hist) - 1 else 'disabled')
        except Exception:
            pass

    def _nav_back(self):
        """Go back to the previous screen."""
        hist = getattr(self, '_screen_history', []) or []
        idx = getattr(self, '_history_index', -1)
        if idx > 0:
            self._history_index = idx - 1
            self._open_screen_by_id(hist[idx - 1])
        self._update_nav_history_buttons()

    def _nav_forward(self):
        """Go forward to the next screen."""
        hist = getattr(self, '_screen_history', []) or []
        idx = getattr(self, '_history_index', -1)
        if 0 <= idx < len(hist) - 1:
            self._history_index = idx + 1
            self._open_screen_by_id(hist[idx + 1])
        self._update_nav_history_buttons()

    def _open_screen_by_id(self, screen_id):
        """Re-open a screen from history without pushing a new entry."""
        # Map screen IDs to their opener methods
        opener_map = {
            'dashboard': self.show_dashboard,
            'inbox': self.open_inbox_window,
            'roster': self.open_roster_window,
            'schedule': self.open_schedule_window,
            'calendar': self.open_calendar_window,
            'news': self.open_news_window,
            'finances': self.open_finances_window,
            'staff': self.open_staff_management_window,
            'morale': self.open_morale_window,
            'media': self.open_media_center,
            'playoffs': self.open_playoffs_window,
            'development': self.open_development_window,
            'practice': self.open_practice_center,
            'tactics': self.open_tactics_window,
            'stats': self.open_stats_standings_window,
            'ahl': self.open_ahl_stats_window,
            'history': self.open_league_history_window,
            'gm_options': self.open_gm_options_window,
            'settings': self.open_settings_window,
            'free_agency': self.open_free_agency_window,
            'trade': self.open_trade_window,
            'waivers': self.open_waivers_window,
            'draft': self.open_draft_day_central,
        }
        opener = opener_map.get(screen_id)
        if opener:
            # Suppress history push during history navigation
            self._suppress_history = True
            try:
                opener()
            finally:
                self._suppress_history = False
        self._update_nav_history_buttons()

    def refresh_next_day_button(self):
        """Update the fixed Next Day button label/state from continue state."""
        try:
            if self._mp_host_mode() or self._mp_client_mode():
                # MP ready-state labels are painted by
                # _mp_refresh_continue_ui (which covers _next_day_btn too).
                return
            btn = getattr(self, '_next_day_btn', None)
            if btn is None or not btn.winfo_exists():
                return
            label, blockers = self.get_continue_state()
            # Show blocker count on the button when blocked
            text = f"{label} ({len(blockers)})" if blockers else label
            btn.configure(text=text)
        except Exception:
            pass
    def _create_nav_pill(self, parent, text, command, side="left", tooltip=None):
        """Create a pill-style navigation button for the top menu bar.

        CTk-based (was canvas-drawn PillButton): real rounded pill with
        proper hover/pressed states. Auto-sizes to the label text.
        """
        init_ctk_theme()
        try:
            from modern_ui import AppColors
            fg = AppColors.TEXT_SECONDARY
            hover_bg = AppColors.BG_HOVER
        except Exception:
            fg = '#a1a1aa'
            hover_bg = '#1e1e24'

        # Size the pill to its text like the old PillButton did.
        font = (self.FONT_FAMILY, 10, 'bold')
        probe = tk.Label(parent, text=text, font=font)
        try:
            probe.update_idletasks()
            w = probe.winfo_reqwidth() + 28
            h = probe.winfo_reqheight() + 12
        finally:
            probe.destroy()

        pill = ctk.CTkButton(
            parent, text=text, command=command,
            font=font, width=w, height=h,
            fg_color="transparent",
            hover_color=hover_bg,
            text_color=fg,
            corner_radius=h // 2,
            border_width=1,
            border_color=BORDER,
            cursor="hand2",
        )
        pill.pack(side=side, padx=4)
        if tooltip:
            _qol_add_tooltip(pill, tooltip)
        return pill

    def _create_dropdown_menu(self, parent, button_text, menu_items, tooltip=None):
        """Create a dropdown menu button with organized menu items."""
        import tkinter as tk
        
        # Create the main dropdown button as a nav pill.
        # The chevron marks it as a menu, distinct from plain nav pills.
        dropdown_btn = self._create_nav_pill(parent, button_text + " ▾", None,
                                             tooltip=tooltip)
        
        # Create dropdown menu
        dropdown_menu = tk.Menu(self.master, tearoff=0, font=(self.FONT_FAMILY, 9))
        
        # Add menu items with conditional logic
        for item_text, command in menu_items.items():
            # Special handling for Trade Deadline Center - only show on deadline day
            if "Trade Deadline" in item_text and not self.is_trade_deadline_day():
                continue  # Skip this menu item if it's not deadline day
            # Draft Day Central - only show on draft days
            if "Draft Day Central" in item_text and not is_draft_day(self.current_date):
                continue
            # Free Agent Frenzy - only show on July 1
            if "Free Agent Frenzy" in item_text and not is_free_agency_day(self.current_date):
                continue
            dropdown_menu.add_command(label=item_text, command=command)
        
        # Bind button click to show menu
        def show_dropdown(event=None):
            try:
                # Get button position
                x = dropdown_btn.winfo_rootx()
                y = dropdown_btn.winfo_rooty() + dropdown_btn.winfo_height()
                dropdown_menu.post(x, y)
            except:
                pass

        dropdown_btn.configure(command=show_dropdown)

        return dropdown_btn

    # ------------------------------------------------------------------
    # Keyboard shortcuts (quality of life)
    # ------------------------------------------------------------------
    _QOL_TEXT_ENTRY_CLASSES = ('Entry', 'TEntry', 'Text', 'TCombobox',
                               'Combobox', 'TSpinbox', 'Spinbox')
    # Widgets whose own Space/Menu behavior must never be hijacked.
    _QOL_SPACE_BLOCK_CLASSES = ('Button', 'TButton', 'Checkbutton',
                                'TCheckbutton', 'Radiobutton', 'TRadiobutton',
                                'Listbox', 'Menu', 'TScale', 'Scale')

    def _setup_keyboard_shortcuts(self):
        """Bind app-wide keyboard shortcuts: Space, Ctrl+S, Esc, ?."""
        if getattr(self, '_qol_shortcuts_bound', False):
            return
        self._qol_shortcuts_bound = True
        self.bind_all('<Key-space>', self._qol_on_space, add='+')
        self.bind_all('<Control-s>', self._qol_on_quick_save, add='+')
        self.bind_all('<Control-S>', self._qol_on_quick_save, add='+')
        self.bind_all('<Escape>', self._qol_on_escape, add='+')
        self.bind_all('<Key-question>', self._qol_on_cheat_sheet, add='+')

    def _qol_focus_class(self):
        try:
            w = self.focus_get()
        except Exception:
            return ''
        if w is None:
            return ''
        try:
            return w.winfo_class()
        except Exception:
            return ''

    def _qol_typing_focus(self):
        """True when the user is typing in a text entry/combobox."""
        return self._qol_focus_class() in self._QOL_TEXT_ENTRY_CLASSES

    def _qol_modal_open(self):
        """True when a modal (grabbed) dialog is open."""
        try:
            return self.grab_current() is not None
        except Exception:
            return False

    def _qol_on_space(self, event=None):
        """Space: Continue / advance one day (never while typing)."""
        cls = self._qol_focus_class()
        if cls in self._QOL_TEXT_ENTRY_CLASSES + self._QOL_SPACE_BLOCK_CLASSES:
            return None
        if self._qol_modal_open():
            return None
        try:
            self._on_continue_pressed()
        except Exception:
            pass
        return 'break'

    def _qol_on_quick_save(self, event=None):
        """Ctrl+S: quick save without opening the save dialog."""
        if self._qol_typing_focus():
            return None
        if self._qol_modal_open():
            return None
        self._qol_quick_save()
        return 'break'

    def _qol_on_escape(self, event=None):
        """Esc: close the focused dialog (never the main window)."""
        if self._qol_typing_focus():
            return None  # don't yank a dialog away mid-typing
        try:
            w = self.focus_get()
        except Exception:
            return None
        target = None
        seen = set()
        while w is not None and id(w) not in seen:
            seen.add(id(w))
            if isinstance(w, tk.Toplevel):
                target = w
                break
            # in-game popup cards live inside the main window now
            if type(w).__name__ == "InGamePopup":
                target = w
                break
            w = getattr(w, 'master', None)
        if target is None:
            return None
        closer = getattr(target, '_qol_escape_close', None)
        try:
            if callable(closer):
                closer()
            else:
                target.destroy()
        except Exception:
            pass
        return 'break'

    def _qol_on_cheat_sheet(self, event=None):
        """'?': show the keyboard-shortcut cheat sheet."""
        if self._qol_typing_focus():
            return None
        self.show_shortcuts_dialog()
        return 'break'

    def _qol_quick_save(self):
        """Save immediately via the save manager; toast on success."""
        mgr = getattr(self, 'save_manager', None)
        if mgr is None:
            messagebox.showwarning("Quick Save", "The save system is not ready yet.")
            return
        try:
            ok = mgr.save_game(compress=True)
        except Exception as e:
            messagebox.showerror("Quick Save", f"Quick save failed:\n{e}")
            return
        if ok:
            try:
                self.on_game_saved()
            except Exception:
                pass
            self._qol_flash_status("Game saved")
        else:
            messagebox.showwarning(
                "Quick Save",
                "Quick save did not complete. "
                "Use Save/Load > Save Game for full options.")

    def _qol_flash_status(self, text, ms=1600):
        """Tiny transient toast in the bottom-right of the main window."""
        try:
            toast = tk.Toplevel(self)
        except Exception:
            return
        toast.overrideredirect(True)
        toast.configure(bg='#16161a')
        tk.Label(toast, text=text, bg='#16161a', fg='#00ceb8',
                 font=(self.FONT_FAMILY, 10, 'bold'), padx=16, pady=10).pack()
        try:
            self.update_idletasks()
            x = (self.winfo_rootx() + self.winfo_width()
                 - toast.winfo_reqwidth() - 24)
            y = (self.winfo_rooty() + self.winfo_height()
                 - toast.winfo_reqheight() - 24)
            toast.geometry(f"+{max(0, x)}+{max(0, y)}")
            toast.attributes('-topmost', True)
            toast.after(ms, toast.destroy)
        except Exception:
            try:
                toast.destroy()
            except Exception:
                pass

    def show_shortcuts_dialog(self):
        """Cheat-sheet dialog listing every keyboard shortcut."""
        if getattr(self, '_qol_cheat_open', False):
            return
        self._qol_cheat_open = True
        dlg = InGamePopup(self)
        dlg.title("Keyboard Shortcuts")
        dlg.transient(self)
        dlg.resizable(False, False)
        dlg.configure(bg='#0e0e11')

        def _close():
            self._qol_cheat_open = False
            try:
                dlg.destroy()
            except Exception:
                pass

        tk.Label(dlg, text="Keyboard Shortcuts", bg='#0e0e11', fg='#ffffff',
                 font=(self.FONT_FAMILY, 14, 'bold')).pack(
                     anchor='w', padx=20, pady=(18, 4))
        tk.Label(dlg, text="Shortcuts stay quiet while you are typing in a text field.",
                 bg='#0e0e11', fg='#71717a',
                 font=(self.FONT_FAMILY, 9, 'italic')).pack(
                     anchor='w', padx=20, pady=(0, 10))

        rows = [
            ("Space", "Continue \u2014 advance to the next day"),
            ("Ctrl+S", "Quick save the game"),
            ("Esc", "Close the focused window or dialog"),
            ("?", "Show this cheat sheet"),
        ]
        grid = tk.Frame(dlg, bg='#0e0e11')
        grid.pack(fill='x', padx=20, pady=(0, 8))
        for i, (key, desc) in enumerate(rows):
            tk.Label(grid, text=key, bg='#1e1e24', fg='#00ceb8',
                     font=(self.FONT_FAMILY, 10, 'bold'), padx=10, pady=6,
                     width=8).grid(row=i, column=0, sticky='w', pady=3)
            tk.Label(grid, text=desc, bg='#0e0e11', fg='#a1a1aa',
                     font=(self.FONT_FAMILY, 10)).grid(
                         row=i, column=1, sticky='w', padx=(12, 0), pady=3)

        tk.Button(dlg, text="Close", command=_close,
                  bg='#00ceb8', fg='#0e0e11', activebackground='#00a894',
                  activeforeground='#0e0e11', relief='flat', padx=24, pady=8,
                  font=(self.FONT_FAMILY, 10, 'bold')).pack(pady=(4, 18))
        dlg.protocol("WM_DELETE_WINDOW", _close)
        dlg._qol_escape_close = _close  # Esc runs the graceful close
        try:
            dlg.update_idletasks()
            x = (self.winfo_rootx()
                 + (self.winfo_width() - dlg.winfo_reqwidth()) // 2)
            y = (self.winfo_rooty()
                 + (self.winfo_height() - dlg.winfo_reqheight()) // 3)
            dlg.geometry(f"+{max(0, x)}+{max(0, y)}")
        except Exception:
            pass

    def _create_panel(self, parent, title, row, col, rowspan=1, colspan=1):
        outer_frame = ttk.Frame(parent, style='Panel.TFrame', padding=1)
        outer_frame.grid(row=row, column=col, rowspan=rowspan, columnspan=colspan, sticky="nsew", padx=0, pady=8)
        
        frame = ttk.Frame(outer_frame, style='Panel.TFrame')
        frame.grid(row=0, column=0, sticky='nsew')

        title_bar = ttk.Frame(frame, style='TitleBar.TFrame')
        title_bar.grid(row=0, column=0, sticky='ew')
        ttk.Label(title_bar, text=title, style='Title.TLabel', padding=(10, 5)).grid(row=0, column=0, sticky='ew')
        return frame
        
    def _create_packed_panel(self, parent, title):
        """Creates a panel that uses pack layout instead of grid."""
        outer_frame = ttk.Frame(parent, style='Panel.TFrame', padding=1)
        outer_frame.pack(fill='both', expand=True, padx=0, pady=8)
        
        frame = ttk.Frame(outer_frame, style='Panel.TFrame')
        frame.pack(fill='both', expand=True)

        title_bar = ttk.Frame(frame, style='TitleBar.TFrame')
        title_bar.pack(fill='x')
        
        ttk.Label(title_bar, text=title, style='Title.TLabel', padding=(10, 5)).pack(side='left')
        return frame

